# R19 wave 3 (review 2026-11-01): reading question types for B2–C2 on new hand-written passages for older children and young teens.
#   events / tf (True / False / Not given) / findword – same shapes as r19_read.py (A1–B1)
#   headings – match-the-headings: a multi-paragraph text (paragraphs split by a blank line), one heading per paragraph in
#              order plus one extra heading that fits none; every heading carries a note saying where it fits or why it doesn't.
#              {type, q, headings:[…in paragraph order], extra:[heading], notes:{heading: why}, explain}
from r19_read import ev, fw, tf, P

HQ = "Match a heading to each paragraph. Tap the heading for paragraph 1 first. One heading is extra."
def B(title, text, *qs): return P(title, text, *qs, three=True, kind="text")

def H(title, paras, extra, *qs):
    """paras: [(paragraph text, heading, note saying why the heading fits it)], extra: (heading, why it fits no paragraph)."""
    notes = {h: f"Paragraph {i + 1}: {why}" for i, (_, h, why) in enumerate(paras)}
    notes[extra[0]] = f"This heading is the extra one. {extra[1]}"
    hd = {"type": "headings", "q": HQ, "headings": [h for _, h, _ in paras], "extra": [extra[0]], "notes": notes,
          "explain": "Read the first and last sentence of each paragraph: they usually say what the whole paragraph is about."}
    return B(title, "\n\n".join(t for t, _, _ in paras), hd, *qs)

